H.background();
const T = Math.max(P.T, 0.1);
const N0 = 1000;
const tMaxPlot = 5 * T;
const tcur = (t * 0.6) % tMaxPlot;
const Ncur = N0 * Math.pow(0.5, tcur / T);
const v = H.plot2d({ xMin: 0, xMax: tMaxPlot, yMin: 0, yMax: N0 * 1.08 });
v.grid(); v.axes();
v.fn(x => N0 * Math.pow(0.5, x / T), { color: H.colors.accent, width: 3 });
for (let k = 1; k <= 5; k++) {
  const xk = k * T;
  if (xk <= tMaxPlot) {
    const yk = N0 * Math.pow(0.5, k);
    v.line(xk, 0, xk, yk, { color: H.colors.grid, width: 1, dash: [4, 4] });
    v.dot(xk, yk, { r: 4, fill: H.colors.violet });
  }
}
v.dot(tcur, Ncur, { r: 7, fill: H.colors.accent2 });
H.text("Radioactive decay: N = N0 (1/2)^(t/T)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Each half-life T halves the remaining nuclei", 24, 52, { color: H.colors.sub, size: 13 });
H.text("T = " + T.toFixed(1) + " s   t = " + tcur.toFixed(1) + " s", 24, 78, { color: H.colors.sub, size: 13 });
H.text("N = " + Math.round(Ncur) + " of " + N0 + " nuclei", 24, 98, { color: H.colors.accent2, size: 13 });
